import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"是否采用插件化架构","description":"","frontmatter":{"title":"是否采用插件化架构","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/architecture/plugin-system.md","filePath":"frontend/decisions/architecture/plugin-system.md","lastUpdated":1785589115000}'),i={name:"frontend/decisions/architecture/plugin-system.md"};function l(o,t,h,n,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="是否采用插件化架构" tabindex="-1">是否采用插件化架构 <a class="header-anchor" href="#是否采用插件化架构" aria-label="Permalink to &quot;是否采用插件化架构&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>插件化架构把核心系统与扩展能力之间的变化隔离在稳定契约后面。它适合确实存在多个扩展提供方、不同生命周期或第三方生态的产品；若扩展都由同一团队同时发布，普通模块和配置往往更简单。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>“以后可能扩展”不是建设插件系统的充分理由。插件系统需要定义注册、生命周期、权限、版本、隔离、故障处理和开发者体验，这些成本会长期存在。</p><p>真正的问题是：扩展由谁开发、是否需要独立发布、核心是否能预先知道所有实现，以及扩展失败能否影响宿主。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-契约与安全约束" tabindex="-1">2.1 契约与安全约束 <a class="header-anchor" href="#_2-1-契约与安全约束" aria-label="Permalink to &quot;2.1 契约与安全约束&quot;">​</a></h3><ul><li>插件只能通过公开 API 访问宿主，不得依赖内部对象；</li><li>权限按能力授予，不能因“已安装”获得全部用户和网络权限；</li><li>必须定义插件加载失败、超时和版本不兼容时的宿主行为；</li><li>第三方代码需要签名、来源校验、CSP 和必要的沙箱边界；</li><li>用户数据、遥测和卸载后的残留必须可治理。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较扩展方数量、独立发布价值、运行时隔离、契约稳定性、性能、调试、审核、版本兼容和平台维护成本。插件数量本身不重要，变化是否能独立发生才重要。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-普通模块与条件配置" tabindex="-1">3.1 普通模块与条件配置 <a class="header-anchor" href="#_3-1-普通模块与条件配置" aria-label="Permalink to &quot;3.1 普通模块与条件配置&quot;">​</a></h3><p>宿主在构建时导入所有功能，通过配置启用。适合同一团队、同一版本和受控扩展集，类型和调试体验最好，扩展需要跟随宿主发布。</p><h3 id="_3-2-构建时插件" tabindex="-1">3.2 构建时插件 <a class="header-anchor" href="#_3-2-构建时插件" aria-label="Permalink to &quot;3.2 构建时插件&quot;">​</a></h3><p>插件通过 manifest 和公开接口注册，但仍与宿主一起构建和发布。它建立扩展契约，却不承担远程代码、动态版本和运行时沙箱，适合内部多团队贡献。</p><h3 id="_3-3-运行时第一方插件" tabindex="-1">3.3 运行时第一方插件 <a class="header-anchor" href="#_3-3-运行时第一方插件" aria-label="Permalink to &quot;3.3 运行时第一方插件&quot;">​</a></h3><p>宿主按需加载组织内独立部署的插件。能够分离发布和加载成本，但需要兼容协议、回退、缓存和监控聚合。</p><h3 id="_3-4-第三方插件生态" tabindex="-1">3.4 第三方插件生态 <a class="header-anchor" href="#_3-4-第三方插件生态" aria-label="Permalink to &quot;3.4 第三方插件生态&quot;">​</a></h3><p>外部开发者发布插件，通常需要 iframe、Worker 或受限解释环境提供隔离，并建立审核、签名、权限提示、撤销和市场治理。它是产品与平台战略，不只是代码组织方式。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>普通模块</th><th>构建时插件</th><th>运行时第一方插件</th><th>第三方插件</th></tr></thead><tbody><tr><td>独立发布</td><td>否</td><td>否</td><td>是</td><td>是</td></tr><tr><td>类型与调试</td><td>最好</td><td>好</td><td>中</td><td>最弱</td></tr><tr><td>安全隔离</td><td>无额外要求</td><td>无额外要求</td><td>需隔离故障</td><td>必须强隔离</td></tr><tr><td>版本协议</td><td>内部代码</td><td>公开接口</td><td>兼容矩阵</td><td>长期公共平台</td></tr><tr><td>平台成本</td><td>低</td><td>中</td><td>高</td><td>很高</td></tr><tr><td>适合扩展方</td><td>单团队</td><td>内部多团队</td><td>稳定第一方团队</td><td>外部生态</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>案例：内部分析平台由 5 个业务团队贡献图表、筛选器和导出动作，统一每两周发布；不存在外部开发者，也没有插件独立上线要求。过去主要问题是功能直接读取宿主 Store，升级时互相破坏。</p><p>推荐构建时插件：每个扩展提供 manifest、设置面板和渲染入口，只通过查询、选择状态和通知三个宿主能力工作。插件与宿主一起测试发布，暂不支持远程 URL 或第三方代码。</p><p>这一选择解决契约和所有权问题，同时避开动态加载、安全沙箱和多版本兼容。若未来确实需要独立发布，再基于同一契约验证运行时加载。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>核心系统需要维护插件 SDK、版本策略、示例、契约测试和弃用流程。插件团队获得清晰入口，但不能继续访问所有内部状态，短期改造会变慢。</p><p>宿主应限制同步钩子时长、捕获插件错误并记录插件身份。构建时插件故障仍可能破坏整个页面，因此需要错误边界和启用开关。</p><p>退出路径是把少量稳定插件内联为普通模块；只要 manifest 和领域数据没有成为唯一存储格式，移除插件框架不应要求迁移业务数据。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>只有一两个内部实现且总是一起发布时，普通组合更清楚。</li><li>核心数据模型仍高速变化时，无法承诺稳定插件 API。</li><li>不要用插件系统掩盖缺少模块边界的问题。</li><li>未建立代码来源、权限和撤销机制前，不要加载第三方远程脚本。</li><li>需要强安全隔离时，同一页面 JavaScript 上下文中的“约定”不等于沙箱。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>五个团队如何向分析平台贡献扩展而不依赖宿主内部状态</td></tr><tr><td>硬约束</td><td>同一发布节奏；仅内部代码；宿主故障率不可上升；权限最小化</td></tr><tr><td>候选</td><td>普通模块、构建时插件、运行时插件、第三方插件平台</td></tr><tr><td>决定</td><td>采用构建时 manifest 插件</td></tr><tr><td>公共契约</td><td>查询只读接口、选择状态、通知；不公开完整 Store</td></tr><tr><td>接受代价</td><td>维护 SDK、契约测试和弃用周期</td></tr><tr><td>明确不做</td><td>远程代码、插件市场、多版本宿主兼容</td></tr><tr><td>成功指标</td><td>越界导入为零；插件故障可定位；宿主升级无需批量读取内部实现</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>当至少三个团队持续需要独立发布、统一发布窗口成为可量化瓶颈、第三方生态成为产品目标，或构建时插件数量导致初始加载超预算时复查。若插件 API 每季度都发生破坏性变化，说明边界尚不稳定，应简化而不是升级为运行时平台。</p>',36)])])}const _=a(i,[["render",l]]);export{p as __pageData,_ as default};
